            "Tests/AppTests/AttachmentControllerTests.swift": #"""
import FlightCore
import FlightWeb
import FlightWebTesting
import Foundation
import Testing
@testable import App

/// The upload route, driven the way the transport drives it: the multipart
/// body delivered as a live chunk stream, boundaries free to straddle chunk
/// seams.
@Suite("AttachmentController — streaming multipart upload")
struct AttachmentControllerTests {

    @Test("a file and its form fields arrive, sizes intact")
    func uploadRoundTrip() async throws {
        let container = try TestContainer.build {
            Components(AttachmentController.self)
        }
        let client = try TestClient(container: container)

        let boundary = "----DemoBoundary"
        let filePayload = String(repeating: "b", count: 50_000)
        let wire = Data(
            ("--\(boundary)\r\n"
                + "Content-Disposition: form-data; name=\"caption\"\r\n\r\n"
                + "the quarterly chart\r\n"
                + "--\(boundary)\r\n"
                + "Content-Disposition: form-data; name=\"file\"; filename=\"chart.png\"\r\n"
                + "Content-Type: image/png\r\n\r\n"
                + filePayload + "\r\n"
                + "--\(boundary)--").utf8)
        // Awkward chunk sizes on purpose: the boundary WILL straddle seams.
        let chunks = stride(from: 0, to: wire.count, by: 1_111).map {
            Data(wire[$0..<min($0 + 1_111, wire.count)])
        }

        let response = await client.post(
            "/attachments",
            headers: [.contentType: "multipart/form-data; boundary=\(boundary)"],
            bodyChunks: chunks)
        #expect(response.status == .ok)

        let received = try response.decodeJSON([AttachmentController.Received].self)
        #expect(received.count == 2)
        #expect(received[0].field == "caption")
        #expect(received[0].bytes == "the quarterly chart".utf8.count)
        #expect(received[1].filename == "chart.png")
        #expect(received[1].contentType == "image/png")
        #expect(received[1].bytes == 50_000)
    }

    @Test("a body that is not multipart is refused as a 415")
    func nonMultipartRefused() async throws {
        let container = try TestContainer.build {
            Components(AttachmentController.self)
        }
        let client = try TestClient(container: container)
        let response = await client.post(
            "/attachments",
            headers: [.contentType: "application/json"],
            bodyChunks: [Data("{}".utf8)])
        #expect(response.status == .unsupportedMediaType)
    }
}

"""#,
            "Tests/AppTests/BootstrapTests.swift": #"""
import FlightActuator
import FlightChannels
import FlightCore
import FlightDataPostgres
import FlightPresence
import FlightPubSub
import FlightSecurityCore
import FlightTransport
import FlightWeb
import FlightWebTesting
import Testing

@testable import App

/// Does the application actually start?
///
/// Every other suite here tests a layer. This one tests the wiring: the same
/// modules `main` boots, in the same order, frozen the same way. It exists
/// because nothing did, and a lifetime mistake — a singleton capturing a
/// request-scoped repository — sat undetected in `AppModule` while a hundred
/// green tests ran around it. Freezing the container is where such a mistake
/// surfaces, and freezing is exactly what a test of a single layer skips.
@Suite("The application boots")
struct BootstrapTests {

    /// Everything `main` passes to `Flight.bootstrap`, minus the transport —
    /// binding a socket is not what is under test here.
    private func boot() throws -> Container {
        let configuration = Configuration(values: [
            "app.name": "App",
            "datasource.primary.url": "postgres://localhost/unused",
        ])
        // The same wiring `main`'s composition root performs, for the three
        // modules that take what they provide: PubSub reads configuration,
        // and Channels is built from PubSub's bus plus the channels AppModule
        // declares. The dependency walk cannot do this, which is the point —
        // it is composition, and it belongs in one place.
        // The composition root's own sequence, by hand: the pool and the
        // validator are graph roots, the graph is built from them, and
        // AppModule registers from the graph.
        let postgres = try PostgresDataModule<PrimaryDataSource>(configuration: configuration)
        let auth = DemoAuthModule()
        let graph = try FlightGraph(
            configuration: configuration,
            postgresDataSource: postgres.dataSource,
            tokenValidator: auth.tokenValidator)
        let app = AppModule(graph: graph)
        let pubsub = try FlightPubSubModule(configuration: configuration)
        return try TestContainer.build(configuration: configuration) {
            postgres
            auth
            app
            FlightSecurityModule()
            ActuatorModule()
            pubsub
            try FlightChannelsModule(
                bus: pubsub.bus, configuration: configuration, channels: app.channels)
            try FlightPresenceModule(
                configuration: configuration,
                localBus: pubsub.local,
                gossipBus: pubsub.bus)
        }
    }

    @Test("the container freezes")
    func freezes() throws {
        #expect(throws: Never.self) { try boot() }
    }

    @Test("the demo's own token validator is the one installed")
    func bringYourOwnAuth() throws {
        // FlightSecurityModule installs a generic OIDC validator unless one is
        // already registered. If the module ordering regressed, this resolves
        // the OIDC one — and would have demanded `security.oidc.issuer` above.
        let validator = try boot().resolve((any TokenValidator).self)
        #expect(validator is DemoTokenValidator)
    }

    @Test("nothing long-lived captured a request-scoped repository")
    func lifetimes() throws {
        // The gateway is the seam that keeps this true: singletons and
        // channels hold it, and it opens a scope per call.
        let container = try boot()
        #expect(throws: Never.self) { try container.resolve(RoomDigestService.self) }
        #expect(throws: Never.self) { try container.resolve((any RoomStore).self) }
    }
}

"""#,
            "Tests/AppTests/ChatJobsTests.swift": #"""
import FlightCore
import FlightWebTesting
import Foundation
import Testing

@testable import App

/// A scheduled job is an ordinary method on an ordinary component.
///
/// No scheduler and no database: `ChatJobs` is resolved from a test container
/// with the digest reads stubbed, exactly as `UserServiceTests` resolves a
/// service with its repository stubbed. Whether the job fires at 03:00 is the
/// cron engine's business and is tested there, not here.
@Suite("ChatJobs — jobs as plain methods")
struct ChatJobsTests {

    private struct StubDigests: DigestReading {
        let rooms: [RoomActivity]

        func activity(minimumMessages: Int) async throws -> [RoomActivity] {
            rooms.filter { $0.messages >= minimumMessages }
        }
        func headlines() async throws -> [RoomHeadline] { [] }
    }

    /// Binds the stub under the same key the application binds the real
    /// service under.
    private struct FakeDigests: FlightModule {
        let rooms: [RoomActivity]
        // FlightModule requires a no-argument init — bootstrap instantiates
        // modules itself — so the seeded one is a second initializer, the
        // same shape FakeRepository uses.
        init() { self.rooms = [] }
        init(rooms: [RoomActivity]) { self.rooms = rooms }

        func configure(_ container: Container) throws {
            let rooms = self.rooms
            container.register((any DigestReading).self, scope: .singleton) { _ in
                StubDigests(rooms: rooms)
            }
        }
    }

    private func jobs(rooms: [RoomActivity]) throws -> ChatJobs {
        let container = try TestContainer.build {
            Components(ChatJobs.self)
            FakeDigests(rooms: rooms)
        }
        return try container.resolve(ChatJobs.self)
    }

    @Test("the nightly summary runs against the busy rooms")
    func summaryCountsBusyRooms() async throws {
        let jobs = try jobs(rooms: [
            RoomActivity(room: "general", messages: 42, lastSentAt: Date()),
            RoomActivity(room: "quiet", messages: 1, lastSentAt: nil),
        ])
        try await jobs.nightlySummary()
    }

    @Test("warming the digests asks for the headlines")
    func warmingReadsHeadlines() async throws {
        try await jobs(rooms: []).warmDigests()
    }
}

"""#,
            "Tests/AppTests/DemoTokenValidatorTests.swift": #"""
import FlightSecurityCore
import Testing

@testable import App

/// The bring-your-own-auth seam, tested as the contract it is.
///
/// These assertions are about `DemoTokenValidator` specifically, but the shape
/// is the point: a `TokenValidator` turns an opaque string into a `Principal`
/// or throws a typed reason, and everything above it — the middleware, the
/// handler guards, the WebSocket upgrade — is written against that contract
/// rather than against any particular provider.
@Suite("Demo token validator — the BYOA seam")
struct DemoTokenValidatorTests {

    @Test("a bare subject becomes a principal with no roles")
    func bareSubject() async throws {
        let principal = try await DemoTokenValidator().validate("demo:ada")
        #expect(principal.subject == "ada")
        #expect(principal.roles.isEmpty)
        // The issuer marks these as locally minted, so a demo principal can
        // never be mistaken for a federated one in a log.
        #expect(principal.issuer == DemoTokenValidator.issuer)
    }

    @Test("roles ride along after the second colon")
    func roles() async throws {
        let principal = try await DemoTokenValidator().validate("demo:ada:moderator,author")
        #expect(principal.subject == "ada")
        #expect(principal.roles == ["moderator", "author"])
        #expect(principal.hasRole("moderator"))
        #expect(!principal.hasRole("admin"))
    }

    @Test("a body containing colons does not leak into the subject")
    func subjectStopsAtTheFirstColon() async throws {
        // maxSplits: 2 means everything after the second colon is the role
        // list, so a role string with a colon in it cannot silently extend
        // the subject.
        let principal = try await DemoTokenValidator().validate("demo:ada:a:b")
        #expect(principal.subject == "ada")
    }

    @Test("tokens that are not demo tokens are rejected, not guessed at")
    func rejectsForeignTokens() async throws {
        let validator = DemoTokenValidator()
        for bad in ["", "ada", "bearer:ada", "demo:", "eyJhbGciOiJIUzI1NiJ9.e30.x"] {
            await #expect(throws: TokenValidationError.self) {
                try await validator.validate(bad)
            }
        }
    }

    @Test("an empty role list is empty, not a role named \"\"")
    func emptyRolesAreDropped() async throws {
        let principal = try await DemoTokenValidator().validate("demo:ada:")
        #expect(principal.roles.isEmpty)
    }
}

"""#,
            "Tests/AppTests/RealtimeTests.swift": #"""
import FlightChannels
import FlightChannelsClient
import FlightChannelsProtocol
import FlightChannelsTesting
import FlightCore
import FlightPresence
import FlightPresenceClient
import FlightPubSub
import FlightSecurityCore
import FlightWeb
import FlightWebTesting
import Foundation
import Testing

@testable import App

/// The demo's real-time path, end to end: a real `ChannelClient` over a real
/// upgrade, through the real Channels router, the real PubSub fan-out, and the
/// real Presence CRDT. Only the database is faked.
///
/// This is the suite that proves the thing the demo previously only claimed —
/// that a chat app built on Flight actually delivers messages and presence to
/// the people in the room.
private struct RealtimeModule: FlightModule {
    static var dependencies: [any FlightModule.Type] {
        [FlightChannelsModule.self, FlightPresenceModule.self]
    }

    let store: FakeRoomStore

    /// The same shape `AppModule` uses: the channel is a value this module
    /// holds, so Channels is built *from* it rather than collecting it.
    let channels: [ChannelRegistration] = [
        ChannelRegistration("room:*", source: "RealtimeModule") { context in
            RoomChannel(
                broadcaster: try context.resolve(ChannelBroadcaster.self),
                presence: try context.resolve((any Presence).self),
                chat: try context.resolve((any RoomStore).self),
                digests: NoopDigests())
        }
    ]

    /// `FlightModule` requires a no-argument init because bootstrap
    /// instantiates modules itself. `TestContainer.build` takes ready-made
    /// *instances* though, so the real initializer below is the one the suite
    /// uses — and each test gets its own store, which matters because
    /// swift-testing runs tests in parallel.
    init() { self.store = FakeRoomStore() }

    init(store: FakeRoomStore) { self.store = store }

    func configure(_ container: Container) throws {
        let store = self.store
        container.register((any RoomStore).self, scope: .singleton) { _ in store }
        container.register((any TokenValidator).self, scope: .singleton) { _ in
            DemoTokenValidator()
        }
        // The real route, not a stand-in: `SocketController` is what the
        // application ships, so registering it here is what makes these
        // tests exercise the upgrade path users actually get.
        try SocketController._flightRegister(container)
    }
}

private struct Harness {
    let container: Container
    let testClient: TestClient
    let store: FakeRoomStore

    init(store: FakeRoomStore) throws {
        self.store = store
        let configuration = Configuration(values: [
            "flight.channels.heartbeat-check-interval-seconds": "0.05"
        ])
        // The wiring, written out: PubSub's bus and this module's declared
        // channels are what Channels is built from. Both take what they
        // provide, so neither can be instantiated from its type.
        let pubsub = try FlightPubSubModule(configuration: configuration)
        let realtime = RealtimeModule(store: store)
        self.container = try TestContainer.build(configuration: configuration) {
            pubsub
            realtime
            try FlightChannelsModule(
                bus: pubsub.bus, configuration: configuration, channels: realtime.channels)
            // No adapter: a single-node test. That is now stated rather than
            // discovered by Presence probing the container for one.
            try FlightPresenceModule(
                configuration: configuration,
                localBus: pubsub.local,
                gossipBus: pubsub.bus)
        }
        self.testClient = try TestClient(container: container)
    }

    /// A client authenticated as `subject`. The token rides in the query
    /// string because a browser cannot set headers on a WebSocket handshake —
    /// the same reason the real app reads it there.
    func client(as subject: String, roles: String = "") -> ChannelClient {
        let token = roles.isEmpty ? "demo:\(subject)" : "demo:\(subject):\(roles)"
        return ChannelClient(
            url: URL(string: "flight-test:///socket")!,
            transport: InMemoryChannelTransport(testClient: testClient, query: "token=\(token)"))
    }

    /// A client with no credential at all.
    func anonymousClient() -> ChannelClient {
        ChannelClient(
            url: URL(string: "flight-test:///socket")!,
            transport: InMemoryChannelTransport(testClient: testClient))
    }
}

@Suite("Demo real-time — channels, presence, and the join gate")
struct RealtimeTests {

    @Test("an authenticated join is admitted and answers with the room")
    func joinAdmitsAuthenticated() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let client = harness.client(as: "ada")
        try await client.connect()

        let reply = try await client.channel("room:general").join()

        #expect(reply["room"]?.stringValue == "general")
        #expect(reply["name"]?.stringValue == "General")
        await client.disconnect()
    }

    @Test("an anonymous socket cannot join a room")
    func joinRejectsAnonymous() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let client = harness.anonymousClient()
        try await client.connect()

        // The gate is the join, not the connect: an anonymous socket is a
        // legitimate thing to hold — it simply cannot enter a room.
        await #expect(throws: (any Error).self) {
            try await client.channel("room:general").join()
        }
        await client.disconnect()
    }

    @Test("a room that does not exist is refused, not conjured")
    func joinRejectsUnknownRoom() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let client = harness.client(as: "ada")
        try await client.connect()

        await #expect(throws: (any Error).self) {
            try await client.channel("room:nonexistent").join()
        }
        await client.disconnect()
    }

    @Test("an archived room is refused")
    func joinRejectsArchivedRoom() async throws {
        let harness = try Harness(
            store: FakeRoomStore(rooms: [.fixture(slug: "attic", archived: true)]))
        let client = harness.client(as: "ada")
        try await client.connect()

        await #expect(throws: (any Error).self) {
            try await client.channel("room:attic").join()
        }
        await client.disconnect()
    }

    @Test("a message is persisted before it is broadcast")
    func messagePersistedThenBroadcast() async throws {
        let store = FakeRoomStore(rooms: [.fixture(slug: "general")])
        let harness = try Harness(store: store)
        let ada = harness.client(as: "ada")
        try await ada.connect()
        let channel = ada.channel("room:general")
        _ = try await channel.join()

        let reply = try await channel.push("new_msg", payload: ["body": "hello"])

        // The sender gets the canonical row back, so an optimistic render can
        // be reconciled against what was actually stored.
        #expect(reply["body"]?.stringValue == "hello")
        #expect(reply["sender"]?.stringValue == "ada")
        #expect(reply["id"]?.stringValue != nil)
        #expect(store.posted.count == 1)
        #expect(store.posted.first?.body == "hello")
        await ada.disconnect()
    }

    @Test("a failed write broadcasts nothing")
    func failedWriteDoesNotBroadcast() async throws {
        let store = FakeRoomStore(rooms: [.fixture(slug: "general")])
        store.failPosts()
        let harness = try Harness(store: store)

        let ada = harness.client(as: "ada")
        try await ada.connect()
        let adaChannel = ada.channel("room:general")
        _ = try await adaChannel.join()

        let bob = harness.client(as: "bob")
        try await bob.connect()
        let bobChannel = bob.channel("room:general")
        _ = try await bobChannel.join()

        let seen = MessageCollector(channel: bobChannel, event: "new_msg")

        await #expect(throws: (any Error).self) {
            try await adaChannel.push("new_msg", payload: ["body": "doomed"])
        }

        // Nothing stored, so nothing may have been seen. A message that fans
        // out and then fails to insert has been read by everyone and exists
        // for no one — which no retry can repair.
        #expect(store.posted.isEmpty)
        try await Task.sleep(for: .milliseconds(120))
        #expect(await seen.count == 0)

        await ada.disconnect()
        await bob.disconnect()
    }

    @Test("a message reaches the other people in the room, not its sender")
    func broadcastReachesOthers() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))

        let ada = harness.client(as: "ada")
        try await ada.connect()
        let adaChannel = ada.channel("room:general")
        _ = try await adaChannel.join()

        let bob = harness.client(as: "bob")
        try await bob.connect()
        let bobChannel = bob.channel("room:general")
        _ = try await bobChannel.join()

        let bobSaw = MessageCollector(channel: bobChannel, event: "new_msg")
        let adaSaw = MessageCollector(channel: adaChannel, event: "new_msg")

        _ = try await adaChannel.push("new_msg", payload: ["body": "hello room"])
        try await Task.sleep(for: .milliseconds(150))

        #expect(await bobSaw.bodies == ["hello room"])
        // The sender already has it, as the push reply — delivering it twice
        // is what `excluding:` exists to prevent.
        #expect(await adaSaw.count == 0)

        await ada.disconnect()
        await bob.disconnect()
    }

    @Test("presence lists everyone in the room, and drops them when they go")
    func presenceTracksMembership() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let presence = try harness.container.resolve((any Presence).self)

        let ada = harness.client(as: "ada")
        try await ada.connect()
        _ = try await ada.channel("room:general").join()

        let bob = harness.client(as: "bob")
        try await bob.connect()
        _ = try await bob.channel("room:general").join()

        try await eventually { await presence.list(topic: "room:general").count == 2 }
        let keys = await presence.list(topic: "room:general").map(\.key).sorted()
        #expect(keys == ["ada", "bob"])

        // Nothing calls untrack. Presence is bound to the socket's membership,
        // so dropping the connection is what removes them.
        await bob.disconnect()
        try await eventually { await presence.list(topic: "room:general").count == 1 }
        let remaining = await presence.list(topic: "room:general").map(\.key)
        #expect(remaining == ["ada"])

        await ada.disconnect()
    }

    @Test("one identity in two tabs is one key with two metas")
    func oneIdentityManyConnections() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let presence = try harness.container.resolve((any Presence).self)

        let tabOne = harness.client(as: "ada")
        try await tabOne.connect()
        _ = try await tabOne.channel("room:general").join()

        let tabTwo = harness.client(as: "ada")
        try await tabTwo.connect()
        _ = try await tabTwo.channel("room:general").join()

        try await eventually {
            await presence.list(topic: "room:general").first?.metas.count == 2
        }
        let entries = await presence.list(topic: "room:general")
        #expect(entries.count == 1, "one identity is one key")
        #expect(entries.first?.metas.count == 2, "two connections are two metas")

        // Closing one tab leaves the person present through the other — the
        // distinction a bare list of names would lose.
        await tabOne.disconnect()
        try await eventually {
            await presence.list(topic: "room:general").first?.metas.count == 1
        }
        #expect(await presence.list(topic: "room:general").count == 1)

        await tabTwo.disconnect()
    }

    @Test("an unknown status is refused rather than recorded")
    func statusValidation() async throws {
        let harness = try Harness(store: FakeRoomStore(rooms: [.fixture(slug: "general")]))
        let ada = harness.client(as: "ada")
        try await ada.connect()
        let channel = ada.channel("room:general")
        _ = try await channel.join()

        let ok = try await channel.push("status", payload: ["status": "away"])
        #expect(ok["status"]?.stringValue == "away")

        await #expect(throws: (any Error).self) {
            try await channel.push("status", payload: ["status": "invisible"])
        }
        await ada.disconnect()
    }
}

// MARK: - Test support

/// The real-time path's only use of the digest service is "tell it something
/// changed"; nothing here asserts on caching, so the seam is satisfied and
/// ignored.
private struct NoopDigests: DigestInvalidating {
    func messagesChanged() async throws {}
}

/// Collects inbound events of one name from a channel.
private actor MessageCollector {
    private var received: [JSONValue] = []

    init(channel: ChannelHandle, event: String) {
        Task { [weak self] in
            for await message in await channel.messages() where message.event == event {
                await self?.append(message.payload)
            }
        }
    }

    private func append(_ payload: JSONValue) { received.append(payload) }

    var count: Int { received.count }
    var bodies: [String] { received.compactMap { $0["body"]?.stringValue } }
}

/// Polls until `condition` holds or the deadline passes — the shape every
/// assertion about a distributed side effect needs, since "has the diff
/// arrived yet" is not answerable synchronously.
private func eventually(
    timeout: Duration = .seconds(2),
    _ condition: () async -> Bool
) async throws {
    let deadline = ContinuousClock.now.advanced(by: timeout)
    while ContinuousClock.now < deadline {
        if await condition() { return }
        try await Task.sleep(for: .milliseconds(20))
    }
    Issue.record("condition never became true within \(timeout)")
}

"""#,
            "Tests/AppTests/RoomChannelTests.swift": #"""
import FlightChannelsProtocol
import Foundation
import Testing

@testable import App

/// The decisions `RoomChannel` makes before it ever touches a database.
///
/// Topic parsing and the wire shape are worth pinning on their own: the topic
/// is what authorization keys off, and the wire shape is a contract two
/// separate code paths (the WebSocket handler and the REST controller) both
/// produce. If those two ever disagree, clients see the same message in two
/// shapes depending on how it was sent.
@Suite("RoomChannel — topic parsing and wire shape")
struct RoomChannelTests {

    @Test("a well-formed topic yields its room slug")
    func topicParsing() {
        #expect(RoomChannel.roomSlug(from: "room:general") == "general")
        #expect(RoomChannel.roomSlug(from: "room:a:b") == "a:b")
    }

    @Test("anything that is not this channel's shape is refused, not coerced")
    func malformedTopics() {
        // "room:" is the interesting one: dropping the prefix leaves an empty
        // string, and treating that as a room named "" would create presence
        // lists for a room nobody can name.
        for bad in ["room:", "room", "lobby", "", "rooms:general", "Room:general"] {
            #expect(RoomChannel.roomSlug(from: bad) == nil, "\(bad) should not parse")
        }
    }

    @Test("the wire shape carries exactly the public fields")
    func wireShape() throws {
        let id = UUID()
        let message = ChatMessage(
            id: id, room: "general", roomID: UUID(), sender: "ada",
            body: "hello", authorID: nil, parentID: nil,
            mentions: ["grace"], sentAt: Date(timeIntervalSince1970: 0))

        let wire = RoomChannel.wire(message)

        #expect(wire["id"]?.stringValue == id.uuidString)
        #expect(wire["room"]?.stringValue == "general")
        #expect(wire["sender"]?.stringValue == "ada")
        #expect(wire["body"]?.stringValue == "hello")
        if case .array(let mentions)? = wire["mentions"] {
            #expect(mentions.compactMap(\.stringValue) == ["grace"])
        } else {
            Issue.record("mentions should be an array")
        }
        // Internal identifiers stay internal: a client has no use for the
        // room's UUID when it already addressed the room by slug, and
        // `redacted`/`authorID` are not this event's business.
        #expect(wire["roomID"] == nil)
        #expect(wire["authorID"] == nil)
    }

    @Test("mentions are read defensively from client payload")
    func mentionsParsing() {
        #expect(RoomChannel.mentions(in: ["mentions": .array([.string("ada")])]) == ["ada"])
        // Absent, wrong-typed, and mixed payloads all degrade to something
        // sane rather than throwing — this is client input.
        #expect(RoomChannel.mentions(in: ["body": "hi"]).isEmpty)
        #expect(RoomChannel.mentions(in: ["mentions": "ada"]).isEmpty)
        #expect(RoomChannel.mentions(in: ["mentions": .array([.string("a"), .number(1)])]) == ["a"])
    }

    @Test("only known statuses are accepted")
    func statuses() {
        #expect(RoomChannel.allowedStatuses.contains("online"))
        #expect(RoomChannel.allowedStatuses.contains("away"))
        #expect(RoomChannel.allowedStatuses.contains("typing"))
        #expect(!RoomChannel.allowedStatuses.contains("invisible"))
    }
}

"""#,
            "Tests/AppTests/Support/FakeRoomStore.swift": #"""
import Foundation
import Synchronization

@testable import App

/// An in-memory `RoomStore`, so the real-time suite exercises the real
/// Channels/PubSub/Presence stack with no database anywhere in it.
///
/// It records what was written, which is how the tests assert the property
/// that matters most in `RoomChannel`: the message is persisted *before* it is
/// broadcast, never the other way round.
final class FakeRoomStore: RoomStore, Sendable {
    struct State {
        var rooms: [String: Room] = [:]
        var authors: [String: UUID] = [:]
        var posted: [ChatMessage] = []
        /// Set to make `post` fail, so the broadcast-on-failure path can be
        /// tested rather than assumed.
        var postFails = false
    }

    private let state = Mutex(State())

    init(rooms: [Room] = [], authors: [String: UUID] = [:]) {
        state.withLock {
            $0.rooms = Dictionary(uniqueKeysWithValues: rooms.map { ($0.slug, $0) })
            $0.authors = authors
        }
    }

    var posted: [ChatMessage] { state.withLock { $0.posted } }

    func failPosts() { state.withLock { $0.postFails = true } }

    // MARK: RoomStore

    func room(slug: String, messageLimit: Int) async throws -> Room? {
        state.withLock { $0.rooms[slug] }
    }

    func authorIDs(forNames names: [String]) async throws -> [String: UUID] {
        state.withLock { store in
            store.authors.filter { names.contains($0.key) }
        }
    }

    func post(_ messages: [ChatMessage]) async throws -> [ChatMessage] {
        try state.withLock { store in
            if store.postFails { throw FakeError.postRefused }
            store.posted.append(contentsOf: messages)
            return messages
        }
    }

    enum FakeError: Error { case postRefused }
}

extension Room {
    /// A room with the fields the real-time path reads; the rest is filler.
    static func fixture(slug: String, name: String? = nil, archived: Bool = false) -> Room {
        Room(
            id: UUID(), slug: slug, name: name ?? slug.capitalized,
            archived: archived, createdAt: Date())
    }
}

"""#,
            "Tests/AppTests/Support/MockUserRepository.swift": #"""
import FlightCore
import FlightDataPostgres
import Foundation
import Synchronization
@testable import App

/// An in-memory stand-in for `UserRepository` — no container, no Postgres,
/// just a fixed set of users. `Mutex`-guarded state so the type is genuinely
/// `Sendable`, the same shape as the project's other recording fakes
/// (`RecordingCoordinator`, `RecordingAdapter`, `InMemoryDataSource`).
final class MockUserRepository: UserRepositoryProtocol, Sendable {
    private struct State {
        var users: [User]
        var appliedChangesets: [Changeset<User>] = []
    }
    private let state: Mutex<State>

    init(users: [User] = []) {
        state = Mutex(State(users: users))
    }

    /// What `apply(_:)` was called with, in order — lets a test assert a
    /// mutation happened without caring how the repository would have
    /// executed it against a real database.
    var appliedChangesets: [Changeset<User>] { state.withLock { $0.appliedChangesets } }

    func all() async throws -> [User] {
        state.withLock { $0.users }
    }

    func find(byID id: UUID) async throws -> User? {
        state.withLock { $0.users.first { $0.id == id } }
    }

    func find(byEmail email: String) async throws -> User? {
        state.withLock { $0.users.first { $0.email == email } }
    }

    func apply(_ changeset: Changeset<User>) async throws {
        state.withLock { $0.appliedChangesets.append(changeset) }
    }
}

/// Binds the fake under the same key the application binds the real
/// repository under.
struct FakeRepository: FlightModule {
    let repository: MockUserRepository
    init() { self.repository = MockUserRepository(users: []) }
    init(_ repository: MockUserRepository) { self.repository = repository }

    func configure(_ container: Container) throws {
        let repository = self.repository
        container.register((any UserRepositoryProtocol).self, scope: .singleton) { _ in repository }
    }
}

